    </v-alert>

    <!-- Loading -->
    <v-card v-if="loading" outlined class="pa-6">
      <v-skeleton-loader type="list-item-avatar-two-line@3"></v-skeleton-loader>
    </v-card>

    <template v-else-if="!error">
      <!-- Summary -->
      <div v-if="supervisees.length" class="summary-row mb-4">
        <div class="summary-tile">
          <div class="summary-tile__value">{{ leaves.length }}</div>
          <div class="summary-tile__label">on leave today</div>
        </div>
        <div class="summary-tile">
          <div class="summary-tile__value">{{ recallableCount }}</div>
          <div class="summary-tile__label">can be recalled</div>
        </div>
        <div class="summary-tile">
          <div class="summary-tile__value">{{ supervisees.length }}</div>
          <div class="summary-tile__label">staff you supervise</div>
        </div>
      </div>

      <!-- Empty states -->
      <v-card v-if="!supervisees.length" outlined class="empty-state">
        <v-icon size="44" color="blue-grey lighten-1">mdi-account-group-outline</v-icon>
        <div class="empty-state__title">You don't supervise anyone</div>
        <div class="empty-state__text">
          Staff appear here when their position lists you as their supervisor,
          or while you are acting for a supervisor who is on leave.
        </div>
      </v-card>

      <v-card v-else-if="!leaves.length" outlined class="empty-state">
        <v-icon size="44" color="success">mdi-account-check-outline</v-icon>
        <div class="empty-state__title">Everyone is at work today</div>
        <div class="empty-state__text">
          None of the {{ supervisees.length }} staff you supervise are on leave today.
        </div>
      </v-card>

      <!-- Staff on leave -->
      <div v-else class="leave-list">
        <v-card v-for="item in leaves" :key="item.id" outlined class="leave-card">
          <div class="leave-card__main">
            <v-avatar color="primary" size="44" class="mr-4 flex-shrink-0">
              <span class="white--text font-weight-bold">{{ initials(item.staffName) }}</span>
            </v-avatar>

            <div class="leave-card__who">
              <div class="leave-card__name">{{ item.staffName }}</div>
              <div v-if="item.designation" class="leave-card__designation">
