                dark
                :color="leaveTypeColor(item.categoryId)"
                class="font-weight-bold mb-1"
              >
                {{ item.categoryName }}
              </v-chip>
              <v-chip
                v-if="item.recalled"
                small
                label
                color="amber lighten-4"
                text-color="amber darken-4"
                class="font-weight-bold mb-1 ml-1"
              >
                <v-icon left x-small>mdi-account-arrow-left</v-icon>
                Recalled
              </v-chip>
              <div class="leave-card__dates">
                {{ formatDate(item.startDate) }} – {{ formatDate(item.endDate) }}
                · {{ item.days }} {{ item.days === 1 ? "day" : "days" }}
              </div>
            </div>

            <div class="leave-card__back">
              <div class="leave-card__back-label">Back at work</div>
              <div class="leave-card__back-value">{{ formatDate(item.returnDate) }}</div>
              <div class="leave-card__back-sub">{{ backIn(item.returnDate) }}</div>
            </div>

            <div class="leave-card__actions">
              <v-btn
                text
                small
                color="primary"
                :to="`/custom/leave-request-view?path=/lesotho/components/leave&leave=${item.id}`"
              >
                View
              </v-btn>
              <v-tooltip bottom :disabled="item.recall.allowed">
                <template v-slot:activator="{ on, attrs }">
                  <span v-bind="attrs" v-on="on">
                    <v-btn
                      small
                      depressed
                      color="amber darken-3"
                      :dark="item.recall.allowed"
                      :disabled="!item.recall.allowed"
                      @click="openRecall(item)"
                    >
                      <v-icon left small>mdi-account-arrow-left</v-icon>
                      Recall
                    </v-btn>
                  </span>
                </template>
                <span>{{ item.recall.reason }}</span>
              </v-tooltip>
            </div>
          </div>

          <!-- Progress through the leave -->
          <div class="leave-card__progress">
            <v-progress-linear
