<script>
const LEAVE_PROFILE = "http://ihris.org/fhir/StructureDefinition/leave-request-profile";
// only annual leave can be recalled; other leave types are protected
const RECALLABLE_CATEGORIES = ["annual"];
// keep each search URL a sensible length when someone supervises many staff
const PRACTITIONER_BATCH = 40;

const toISO = (date) => {
  const pad = (n) => String(n).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
};

const parseDate = (value) => {
  if (!value) return null;
  const [year, month, day] = String(value).split("T")[0].split("-").map(Number);
  if (!year) return null;
  return new Date(year, (month || 1) - 1, day || 1);
};

const addDays = (value, days) => {
  const date = parseDate(value);
  if (!date) return "";
  date.setDate(date.getDate() + days);
  return toISO(date);
};

const daysBetween = (from, to) =>
  Math.round((parseDate(to) - parseDate(from)) / (1000 * 60 * 60 * 24));

export default {
  name: "StaffOnLeave",
  props: ["queries"],

  data() {
    return {
      loading: true,
      error: "",
      today: toISO(new Date()),
      supervisorId: "",
      supervisees: [],
      leaves: [],
      recallOpen: false,
      recallLeave: null,
      snackbar: false,
      snackbarMessage: "",
      snackbarColor: "success",
    };
  },

  computed: {
    recallableCount() {
      return this.leaves.filter((l) => l.recall.allowed).length;
    },
  },

  async created() {
    // after a page refresh the logged-in user is still loading, so wait for it
    await this.waitForUser();
    this.supervisorId = this.currentPractitionerId();
    this.load();
  },

  methods: {
    waitForUser() {
      return new Promise((resolve) => {
        if (this.$store.state.user?.obj?.resource) {
          resolve();
          return;
        }
        let timer = null;
        const unwatch = this.$watch(
          () => this.$store.state.user?.obj?.resource,
          (resource) => {
            if (resource) {
              clearTimeout(timer);
              unwatch();
              resolve();
            }
          },
        );
        // give up after 20 seconds; load() then reports the missing link
        timer = setTimeout(() => {
          unwatch();
          resolve();
        }, 20000);
      });
    },

    currentPractitionerId() {
      const ref = this.$store.state.user?.obj?.resource?.extension?.find(
        (ext) =>
          ext.url === "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference",
      )?.valueReference?.reference;
      return ref ? ref.split("/")[1] : "";
    },

    async load() {
      this.loading = true;
      this.error = "";
      this.today = toISO(new Date());
      try {
        if (!this.supervisorId) {
          throw new Error("Your user account isn't linked to a staff record, so your team can't be found.");
        }
        this.supervisees = await this.loadSupervisees();
        this.leaves = this.supervisees.length ? await this.loadLeaves() : [];
      } catch (error) {
        console.error("Error loading staff on leave:", error);
        this.error = error.message || "Couldn't load staff on leave. Try again.";
      } finally {
        this.loading = false;
      }
    },

    async loadSupervisees() {
      const response = await fetch(`/site/general/supervisee/${this.supervisorId}`);
      if (!response.ok) throw new Error("Couldn't load the staff you supervise.");
      const list = (await response.json()) || [];
      // a supervisor acting for someone else may see the same person twice
      const seen = new Set();
      return list.filter((s) => s.id && !seen.has(s.id) && seen.add(s.id));
    },

    async loadLeaves() {
      const byPractitioner = {};
      for (const s of this.supervisees) byPractitioner[s.id] = s;
      const ids = this.supervisees.map((s) => s.id);
      const batches = [];
      for (let i = 0; i < ids.length; i += PRACTITIONER_BATCH) {
        batches.push(ids.slice(i, i + PRACTITIONER_BATCH));
      }

      const bundles = await Promise.all(
        batches.map(async (batch) => {
          const params = new URLSearchParams({
            _profile: LEAVE_PROFILE,
            practitioner: batch.map((id) => `Practitioner/${id}`).join(","),
            // a recalled leave keeps running until the day before they report back
            requeststatus: "approved,recalled",
            startdate: `le${this.today}`,
            enddate: `ge${this.today}`,
            _include: "Basic:leavecategory",
            _count: "200",
          });
          const response = await fetch(`/fhir/Basic?${params.toString()}`);
          if (!response.ok) throw new Error("Couldn't load leave records.");
          return response.json();
        }),
      );

      const categories = {};
      const requests = [];
      for (const bundle of bundles) {
        for (const entry of bundle.entry || []) {
          const resource = entry.resource;
          if (entry.search?.mode === "include") {
            categories[resource.id] = this.ext(resource, "ihris-basic-name", "valueString");
          } else {
            requests.push(resource);
          }
        }
      }

      return requests
        .map((resource) => this.toLeaveItem(resource, byPractitioner, categories))
        .filter(Boolean)
        .sort((a, b) => (a.returnDate || "").localeCompare(b.returnDate || ""));
    },

    toLeaveItem(resource, byPractitioner, categories) {
      const practitionerId = this.ext(resource, "ihris-practitioner-reference", "valueReference")
        ?.reference?.split("/")[1];
      const staff = byPractitioner[practitionerId];
      if (!staff) return null;

      const categoryId = this.ext(resource, "leave-category", "valueReference")?.reference?.split("/")[1] || "";
      const startDate = this.ext(resource, "start-date", "valueDate");
      const endDate = this.ext(resource, "end-date", "valueDate");
      const status = this.ext(resource, "request-status", "valueCoding")?.code;
      const calendarDays = Math.max(1, daysBetween(startDate, endDate) + 1);
      const dayOfLeave = Math.min(calendarDays, Math.max(1, daysBetween(startDate, this.today) + 1));

      return {
        id: resource.id,
        practitionerId,
        staffName: staff.name || "Unknown staff member",
        designation: staff.designation || "",
        categoryId,
        categoryName: categories[categoryId] || categoryId || "Leave",
        startDate,
        endDate,
        returnDate: this.ext(resource, "return-date", "valueDate"),
        days: this.ext(resource, "leave-days", "valueInteger") || 0,
        calendarDays,
        dayOfLeave,
        progress: (dayOfLeave / calendarDays) * 100,
        recalled: status === "recalled",
        recall: this.recallCheck(categoryId, startDate, endDate, status),
      };
    },

    // Mirrors the server rules so the button is only offered when a recall can succeed
    recallCheck(categoryId, startDate, endDate, status) {
      if (status === "recalled") {
        return { allowed: false, reason: "Already recalled. They report back on the date shown." };
      }
      if (!RECALLABLE_CATEGORIES.includes(categoryId)) {
        return { allowed: false, reason: "Only annual leave can be recalled." };
      }
      const earliest = this.today > addDays(startDate, 1) ? this.today : addDays(startDate, 1);
      if (!endDate || earliest > endDate) {
        return { allowed: false, reason: "This leave ends today, so there's no day left to recall to." };
      }
      return { allowed: true, reason: "" };
    },

    ext(resource, name, type) {
      return resource.extension?.find((e) => e.url.endsWith(`/${name}`))?.[type];
    },

    openRecall(item) {
      this.recallLeave = item;
      this.recallOpen = true;
    },

    onRecalled({ recallDate }) {
      const name = this.recallLeave?.staffName || "The staff member";
      this.showSnackbar(`${name} has been recalled and must report back on ${this.formatDate(recallDate)}.`, "success");
      this.load();
    },

    showSnackbar(message, color) {
      this.snackbarMessage = message;
      this.snackbarColor = color;
      this.snackbar = true;
    },

    backIn(returnDate) {
      const days = daysBetween(this.today, returnDate);
      if (isNaN(days)) return "";
      if (days <= 0) return "Today";
      if (days === 1) return "Tomorrow";
      return `In ${days} days`;
    },

    initials(name) {
      const parts = (name || "").split(" ").filter(Boolean);
      if (!parts.length) return "?";
      return (parts[0][0] + (parts.length > 1 ? parts[parts.length - 1][0] : "")).toUpperCase();
    },

    leaveTypeColor(categoryId) {
      const typeMap = {
        annual: "blue",
        maternity: "pink",
        paternity: "indigo",
        compassionate: "purple",
        unpaid: "orange",
        sick: "red",
        stillborn: "deep-purple",
        bonding: "teal",
        study: "green",
      };
      return typeMap[categoryId] || "grey";
    },

    formatDate(value, withWeekday) {
      const date = parseDate(value);
      if (!date) return "N/A";
      return date.toLocaleDateString("en-GB", {
        weekday: withWeekday ? "long" : undefined,
        day: "numeric",
        month: "short",
        year: "numeric",
      });
    },

    goBack() {
      if (window.history.length > 1) {
        this.$router.go(-1);
      } else {
        this.$router.push("/");
      }
    },
  },

  components: {
    "leave-recall": () => import("./leave-recall"),
  },
};
</script>

